def with_pattern(pattern, regex_group_count=None):
    """Attach a regular expression pattern matcher to a custom type converter
    function.

    This annotates the type converter with the :attr:`pattern` attribute.

    EXAMPLE:
        >>> import parse
        >>> @parse.with_pattern(r"\d+")
        ... def parse_number(text):
        ...     return int(text)

    is equivalent to:

        >>> def parse_number(text):
        ...     return int(text)
        >>> parse_number.pattern = r"\d+"

    :param pattern: regular expression pattern (as text)
    :param regex_group_count: Indicates how many regex-groups are in pattern.
    :return: wrapped function
    """
    def decorator(func):
        func.pattern = pattern
        func.regex_group_count = regex_group_count
        return func
    return decorator


# Picklable functors for type conversions (R7)
class FloatConvert:
    """Convert string to float."""
    def __call__(self, s, m):
        return float(s)


class DecimalConvert:
    """Convert string to Decimal."""
    def __call__(self, s, m):
        return Decimal(s)


class PercentageConvert:
    """Convert percentage string to float."""
    def __call__(self, s, m):
        return float(s[:-1]) / 100.


class IntConvertFunctor:
    """Convert string to integer with optional base."""
    def __init__(self, base):
        self.base = base

    def __call__(self, string, match):
        CHARS = '0123456789abcdefghijklmnopqrstuvwxyz'

        if string[0] == '-':
            sign = -1
        else:
            sign = 1

        if string[0] == '0' and len(string) > 2:
            if string[1] in 'bB':
                base = 2
            elif string[1] in 'oO':
                base = 8
            elif string[1] in 'xX':
                base = 16
            else:
                base = self.base
        else:
            base = self.base

        chars = CHARS[:base]
        string = re.sub('[^%s]' % chars, '', string.lower())
        return sign * int(string, base)

    def __repr__(self):
        return f'IntConvertFunctor(base={self.base})'
